mapper.select:
SELECT 
FROM t_deposit


        AND chain = #{chain}


        AND token = #{token}


        AND status = #{statusCode}


        AND created_at >= #{fromCreatedAt}


        AND created_at <= #{toCreatedAt}


ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO t_deposit (
    id, wallet_tx_id, user_id, account_id, chain, token, tx_hash, amount, status,
    credited_at, reversed_at, rejection_reason, rejected_at, created_at
) VALUES (
    #{id}, #{walletTxId}, #{userId}, #{accountId}, #{chain}, #{token}, #{txHash}, #{amount},
    #{statusCode}, #{creditedAt}, #{reversedAt}, #{rejectionReason}, #{rejectedAt}, #{createdAt}
)
